package com.ethk3.novaonepro.strategyv2;
import java.io.*;
/** Expected-score distillation from an explicitly bound legacy preference projection, plus real-label NLL.
 * Teacher preference is not represented as calibrated hit probability or transferred evidence. */
public final class DistillationFamilyR26 implements TemporalModelR26,TrainingDiagnosticsR26 {
    public interface Teacher {double[][] marginal();String identity();}
    private final Teacher teacher;private final String teacherId;private double[][] bias=new double[10][10],context=new double[100][10];private int[] previous;private long t,distilled;private TrainingDiagnosticsR26.Step last;
    public DistillationFamilyR26(Teacher teacher){if(teacher==null||teacher.identity()==null||teacher.identity().isEmpty())throw new IllegalArgumentException("F23_TEACHER_REQUIRED");this.teacher=teacher;teacherId=teacher.identity();}
    private double[][] scores(){return scores(bias,context);}
    private double[][] scores(double[][] b,double[][] c){double[][] s=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++)s[p][n]=b[p][n]+(previous==null?0:c[p*10+n][previous[p]-1]);return s;}
    public void resetTemporalContext(){previous=null;last=null;}
    public int stateWidth(){return 3;}
    public void predict(float[][] p,float[] st){ExactPermutationR26.Result r=ExactPermutationR26.infer(scores(),null);for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=(float)r.marginal[i][j];st[0]=(float)Math.log1p(t);st[1]=(float)Math.log1p(distilled);st[2]=0;}
    public TrainingDiagnosticsR26.Step lastTrainingStep(){return last;}
    public long completedTrainingUpdates(){return t;}
    public String optimizerProtocol(){return "F23_EXACT_JOINT_EXPECTED_SCORE_DISTILLATION_SGD_LR002_CLIP8|KNOWN_LIFETIME";}
    private static double loss(double[][] scores,ExactPermutationR26.Result r,int[] draw,double[][] target,double alpha){double value=r.logZ;for(int p=0;p<10;p++)for(int n=0;n<10;n++)value-=((1-alpha)*(draw[p]==n+1?1:0)+alpha*(target==null?0:target[p][n]))*scores[p][n];return value;}
    public void update(int[] draw){
        OnlineModelsSU2.requireDraw(draw);ExecutionBudgetR26.poll();if(t==Long.MAX_VALUE||distilled==Long.MAX_VALUE)throw new IllegalStateException("F23_UPDATE_CLOCK");if(!teacherId.equals(teacher.identity()))throw new IllegalStateException("F23_TEACHER_IDENTITY_DRIFT");double[][] supplied=teacher.marginal(),target=null;double alpha=supplied==null?0:.35;
        if(supplied!=null){if(supplied.length!=10)throw new IllegalArgumentException("F23_TEACHER_SHAPE");target=new double[10][10];for(int p=0;p<10;p++){if(supplied[p]==null||supplied[p].length!=10)throw new IllegalArgumentException("F23_TEACHER_SHAPE");System.arraycopy(supplied[p],0,target[p],0,10);}for(int p=0;p<10;p++){double row=0,col=0;for(int n=0;n<10;n++){double q=target[p][n];if(!Double.isFinite(q)||q<0||q>1)throw new IllegalArgumentException("F23_TEACHER_RANGE");row+=q;col+=target[n][p];}if(Math.abs(row-1)>1e-6||Math.abs(col-1)>1e-6)throw new IllegalArgumentException("F23_TEACHER_INCOHERENT");}}
        double[][] before=scores();ExactPermutationR26.Result r=ExactPermutationR26.infer(before,null);double[][] nextBias=new double[10][],nextContext=new double[100][];for(int p=0;p<10;p++)nextBias[p]=bias[p].clone();for(int i=0;i<100;i++)nextContext[i]=context[i].clone();double gradient=0,delta=0;
        for(int p=0;p<10;p++)for(int n=0;n<10;n++){double soft=target==null?0:target[p][n],g=r.marginal[p][n]-((1-alpha)*(draw[p]==n+1?1:0)+alpha*soft);gradient+=g*g;nextBias[p][n]=bound(bias[p][n]-.02*g);double d=nextBias[p][n]-bias[p][n];delta+=d*d;if(previous!=null){gradient+=g*g;nextContext[p*10+n][previous[p]-1]=bound(context[p*10+n][previous[p]-1]-.02*g);d=nextContext[p*10+n][previous[p]-1]-context[p*10+n][previous[p]-1];delta+=d*d;}}
        double[][] after=scores(nextBias,nextContext);StringBuilder input=new StringBuilder("F23_FIXED_PRE_LABEL_STUDENT_TEACHER_V1|").append(teacherId).append('|').append(t).append('|').append(alpha);if(previous!=null)for(int x:previous)input.append('|').append(x);if(target!=null)for(double[] row:target)for(double x:row)input.append('|').append(Double.toHexString(x));TrainingDiagnosticsR26.Step step=new TrainingDiagnosticsR26.Step(t+1,loss(before,r,draw,target,alpha),loss(after,ExactPermutationR26.infer(after,null),draw,target,alpha),Math.sqrt(gradient),Math.sqrt(delta),PolicyIdentityR26.sha256(input.toString()),"EXACT_PERMUTATION_LOG_PARTITION_MINUS_BLENDED_TARGET_EXPECTED_SCORE;TRUE_LABEL_AND_FIXED_TEACHER_MARGINAL_WEIGHT="+alpha+";NOT_CALIBRATED_TEACHER_HIT_PROBABILITY;BIAS_AND_ACTIVE_CONTEXT_ONLY");int[] nextPrevious=draw.clone();ExecutionBudgetR26.poll();if(!teacherId.equals(teacher.identity()))throw new IllegalStateException("F23_TEACHER_IDENTITY_DRIFT");bias=nextBias;context=nextContext;previous=nextPrevious;t++;if(target!=null)distilled++;last=step;
    }
    private static double bound(double x){return Math.max(-8,Math.min(8,x));}
    public void write(DataOutput o)throws IOException{o.writeInt(0x26230001);o.writeUTF(teacherId);o.writeLong(t);o.writeLong(distilled);o.writeBoolean(previous!=null);if(previous!=null)for(int n:previous)o.writeInt(n);for(double[][] m:new double[][][]{bias,context})for(double[] row:m)for(double x:row)o.writeDouble(x);}
    public void read(DataInput in)throws IOException{
        if(in.readInt()!=0x26230001||!teacherId.equals(in.readUTF()))throw new IOException("F23_TEACHER_BINDING");long restoredT=in.readLong(),restoredDistilled=in.readLong();int present=in.readUnsignedByte();if(restoredT<0||restoredDistilled<0||restoredDistilled>restoredT||present>1)throw new IOException("F23_CURSOR");int[] restoredPrevious=null;if(present==1){restoredPrevious=new int[10];for(int i=0;i<10;i++)restoredPrevious[i]=in.readInt();try{OnlineModelsSU2.requireDraw(restoredPrevious);}catch(IllegalArgumentException bad){throw new IOException("F23_CONTEXT",bad);}}double[][] restoredBias=new double[10][10],restoredContext=new double[100][10];for(double[][] m:new double[][][]{restoredBias,restoredContext})for(double[] row:m)for(int j=0;j<row.length;j++){row[j]=in.readDouble();if(!Double.isFinite(row[j])||Math.abs(row[j])>8)throw new IOException("F23_PARAMETER");}if(!teacherId.equals(teacher.identity()))throw new IOException("F23_TEACHER_IDENTITY_DRIFT");t=restoredT;distilled=restoredDistilled;previous=restoredPrevious;bias=restoredBias;context=restoredContext;last=null;
    }
}
